head.script:
scwin.trigger1_onclick = function(e) {
    //debugger;
    alert(scwin.$w.getFrameId());
};
scwin.trigger2_onclick = function(e) {
    alert($w.getFrameId());
};
scwin.trigger3_onclick = function(e) {
    var options = {
        id: "popup1",
        type: "wframePopup",
        width: "400px",
        height: "250px",
        modal: false,
        alwaysOnTop: false
        //            , useModalStack: true
    };
    //        debugger;
    $w.openPopup("openPopup_child.xml", options);
};
scwin.trigger4_onclick = function(e) {
    debugger;
    var mainCtn = parent.WebSquare.wUnit.getObjById("windowContainer1");
    //alert(mainCtn.selectedIndex);
    //alert(mainCtn.getSelectedIndex());
    localStorage.setItem("log1", mainCtn.getSelectedIndex());
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    requires("uiplugin.popup");
    debugger;
    window.mainCtn = parent.WebSquare.wUnit.getObjById("windowContainer1");
    //alert(mainCtn.getSelectedIndex());
    localStorage.setItem("log", mainCtn.getSelectedIndex());
    //setTimeout(function(){alert(mainCtn.getSelectedIndex());},1000);
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
